WITH p AS (SELECT coalesce(%s::text,'') ma_vt,coalesce(%s::text,'') ma_kho,%s::integer uid,%s::integer lim),s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR(coalesce(u.ds_branchs,'')='' AND coalesce(u.ds_stocks,'')='') unrestricted FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid),t AS (SELECT a.data_tem->0->>'ma_vt' ma_vt,sum((a.data_tem->0->>'so_luong')::numeric) ton_hien_tai FROM public.intem_log a CROSS JOIN s WHERE s.ok IS NOT NULL AND a.nxt=1 AND a.status='1' AND(s.ma_kho='' OR a.ma_kho=ANY(string_to_array(s.ma_kho,',')))AND(s.unrestricted OR EXISTS(SELECT 1 FROM public.dmkho k WHERE k.ma_kho=a.ma_kho AND k.ma_dvcs=ANY(string_to_array(s.bs,',')))) GROUP BY a.data_tem->0->>'ma_vt') SELECT v.ma_vt,v.ten_vt,v.dvt,v.packs,v.packs0,v.ma_thung,v.so_luong_thung_pallet,t.ton_hien_tai,CASE WHEN coalesce(v.so_luong_thung_pallet,0)=0 THEN NULL ELSE t.ton_hien_tai/v.so_luong_thung_pallet END ton_quy_doi_pallet,count(*) OVER() total FROM public.dmvt v CROSS JOIN s LEFT JOIN t ON t.ma_vt=v.ma_vt WHERE s.ok IS NOT NULL AND(s.ma_vt='' OR v.ma_vt=ANY(string_to_array(s.ma_vt,','))) ORDER BY v.ma_vt LIMIT(SELECT lim FROM p);
